// Aegis Web Console API client.
//
// One place that talks to the local Aegis server. Every state-changing call may
// carry a `request_id` generated by the browser and is only ever retried with
// the SAME id, so the Host can resolve a retry from its committed receipt
// instead of running the prompt twice.

const JSON_HEADERS = { "content-type": "application/json", accept: "application/json" };

export class ApiError extends Error {
    constructor(status, code, message, body) {
        super(message || code || `HTTP ${status}`);
        this.status = status;
        this.code = code || "http_error";
        this.body = body ?? null;
    }

    /** True when retrying the exact same request could be resolved by receipt. */
    get retryable() {
        return this.status === 503 || this.status === 504 || this.code === "host_unavailable";
    }
}

async function call(method, path, body) {
    const response = await fetch(path, {
        method,
        headers: method === "GET" ? { accept: "application/json" } : JSON_HEADERS,
        credentials: "same-origin",
        cache: "no-store",
        body: body === undefined ? undefined : JSON.stringify(body),
    });
    const text = await response.text();
    let parsed = null;

    try {
        parsed = text ? JSON.parse(text) : null;
    } catch {
        parsed = null;
    }

    if (!response.ok) {
        throw new ApiError(
            response.status,
            parsed?.code ?? `http_${response.status}`,
            parsed?.error ?? parsed?.reason ?? `${response.status} ${response.statusText}`,
            parsed,
        );
    }

    return parsed ?? {};
}

/** A request id for one logical user action (kept across retries). */
export function requestId(prefix = "req") {
    const random =
        globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(16).slice(2)}`;

    return `${prefix}:${random}`;
}

export const api = {
    health: () => call("GET", "/api/health"),
    experiments: () => call("GET", "/api/experiments"),
    createExperiment: (body) => call("POST", "/api/experiments", body),
    experiment: (label) => call("GET", `/api/experiments/${encodeURIComponent(label)}`),
    view: (label) => call("GET", `/api/experiments/${encodeURIComponent(label)}/view`),
    attach: (label) => call("POST", `/api/experiments/${encodeURIComponent(label)}/attach`, {}),
    detach: (label) => call("POST", `/api/experiments/${encodeURIComponent(label)}/detach`, {}),
    send: (label, { text, requestId }) =>
        call("POST", `/api/experiments/${encodeURIComponent(label)}/messages`, {
            text,
            request_id: requestId,
        }),
    liveModels: (label) => call("GET", `/api/experiments/${encodeURIComponent(label)}/models`),
    setModel: (label, body) =>
        call("POST", `/api/experiments/${encodeURIComponent(label)}/model`, body),
    pause: (label) => call("POST", `/api/experiments/${encodeURIComponent(label)}/pause`, {}),
    resume: (label) => call("POST", `/api/experiments/${encodeURIComponent(label)}/resume`, {}),
    stop: (label) => call("POST", `/api/experiments/${encodeURIComponent(label)}/stop`, {}),
    models: () => call("GET", "/api/models"),
    tools: () => call("GET", "/api/tools"),
    upload: (label, body) =>
        call("POST", `/api/experiments/${encodeURIComponent(label)}/attachments`, body),
    files: (label, path = "") =>
        call(
            "GET",
            `/api/experiments/${encodeURIComponent(label)}/files?path=${encodeURIComponent(path)}`,
        ),
    file: (label, path) =>
        call(
            "GET",
            `/api/experiments/${encodeURIComponent(label)}/file?path=${encodeURIComponent(path)}`,
        ),
    requestStatus: (label, id) =>
        call("POST", `/api/requests/${encodeURIComponent(id)}`, { label }),
};
